package mx.mesapp.api;

import static mx.mesapp.api.ApiExceptionHandler.ApiProblem.*;
import java.math.BigDecimal;
import java.util.*;
import jakarta.servlet.http.HttpSession;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import mx.mesapp.config.BootstrapData;
import mx.mesapp.domain.OrderStatePolicy;
import mx.mesapp.sync.OutboxSyncWorker;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.web.bind.annotation.*;
import org.springframework.context.annotation.Profile;

@RestController
@Profile("local")
@RequestMapping("/api")
public class OperationalController {
    private final JdbcTemplate jdbc; private final SimpMessagingTemplate ws;private final OutboxSyncWorker syncWorker;private final mx.mesapp.sync.SyncEventService syncEvents;
    public OperationalController(JdbcTemplate jdbc,SimpMessagingTemplate ws,OutboxSyncWorker syncWorker,mx.mesapp.sync.SyncEventService syncEvents){this.jdbc=jdbc;this.ws=ws;this.syncWorker=syncWorker;this.syncEvents=syncEvents;}
    @GetMapping("/health") public Object health(){var body=new HashMap<String,Object>();body.put("local","CONNECTED");body.put("internet",syncWorker.cloudStatus());body.put("pendingSync",jdbc.queryForObject("SELECT count(*) FROM evento_outbox WHERE restaurante_id=? AND estado='PENDIENTE'",Long.class,BootstrapData.RESTAURANT_ID));body.put("lastCentralCheck",syncWorker.lastCheck()==null?"":syncWorker.lastCheck().toString());return body;}
    @GetMapping("/tables") public Object tables(HttpSession s){AuthController.require(s,"MESERO","COCINA","ADMINISTRADOR");return jdbc.queryForList("SELECT m.id,m.numero,m.activa,EXISTS(SELECT 1 FROM pedido p WHERE p.mesa_id=m.id AND p.estado IN ('CONFIRMADO','EN_PREPARACION','LISTO')) AS ocupada FROM mesa m WHERE m.restaurante_id=? ORDER BY m.numero",BootstrapData.RESTAURANT_ID);}
    @Transactional @PostMapping("/tables") public Object createTable(@Valid @RequestBody TableInput i,HttpSession s){AuthController.require(s,"ADMINISTRADOR");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO mesa(id,restaurante_id,numero,version) VALUES (?,?,?,1)",id,BootstrapData.RESTAURANT_ID,i.numero());syncEvents.record(id,1,"MESA_ACTUALIZADA",Map.of("id",id,"numero",i.numero(),"activa",true));return Map.of("id",id,"numero",i.numero(),"activa",true);}
    @Transactional @PatchMapping("/tables/{id}") public Object updateTable(@PathVariable UUID id,@Valid @RequestBody TableUpdate i,HttpSession s){AuthController.require(s,"ADMINISTRADOR");if(jdbc.query("SELECT numero FROM mesa WHERE id=? AND restaurante_id=? FOR UPDATE",rs->rs.next()?rs.getInt(1):null,id,BootstrapData.RESTAURANT_ID)==null)throw missing("Mesa no encontrada");if(!i.activa()&&jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pedido WHERE mesa_id=? AND estado IN ('CONFIRMADO','EN_PREPARACION','LISTO'))",Boolean.class,id))throw conflict("No se puede desactivar una mesa con un pedido activo");jdbc.update("UPDATE mesa SET activa=?,version=version+1 WHERE id=? AND restaurante_id=?",i.activa(),id,BootstrapData.RESTAURANT_ID);long version=jdbc.queryForObject("SELECT version FROM mesa WHERE id=?",Long.class,id);int number=jdbc.queryForObject("SELECT numero FROM mesa WHERE id=?",Integer.class,id);syncEvents.record(id,version,"MESA_ACTUALIZADA",Map.of("id",id,"numero",number,"activa",i.activa()));return Map.of("actualizada",true);}
    @Transactional @DeleteMapping("/tables/{id}") public Object deleteTable(@PathVariable UUID id,HttpSession s){AuthController.require(s,"ADMINISTRADOR");return updateTable(id,new TableUpdate(false),s);}
    @GetMapping("/categories") public Object categories(HttpSession s){AuthController.require(s,"MESERO","ADMINISTRADOR","COCINA");return jdbc.queryForList("SELECT id,nombre,activa FROM categoria WHERE restaurante_id=? ORDER BY nombre",BootstrapData.RESTAURANT_ID);}
    @Transactional @PostMapping("/categories") public Object createCategory(@Valid @RequestBody CategoryInput i,HttpSession s){AuthController.require(s,"ADMINISTRADOR");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO categoria(id,restaurante_id,nombre) VALUES (?,?,?)",id,BootstrapData.RESTAURANT_ID,i.nombre().trim());syncEvents.record(id,1,"CATEGORIA_ACTUALIZADA",Map.of("id",id,"nombre",i.nombre().trim(),"activa",true));return Map.of("id",id,"nombre",i.nombre().trim());}
    @GetMapping("/products") public Object products(HttpSession s){AuthController.require(s,"MESERO","ADMINISTRADOR","COCINA");return jdbc.queryForList("SELECT p.id,p.nombre,p.descripcion,p.precio,p.disponible,p.activo,p.categoria_id,c.nombre AS categoria FROM producto p JOIN categoria c ON c.id=p.categoria_id WHERE p.restaurante_id=? ORDER BY c.nombre,p.nombre",BootstrapData.RESTAURANT_ID);}
    @Transactional @PostMapping("/products") public Object createProduct(@Valid @RequestBody ProductInput i,HttpSession s){AuthController.require(s,"ADMINISTRADOR");if(jdbc.queryForObject("SELECT count(*) FROM categoria WHERE id=? AND restaurante_id=? AND activa",Integer.class,i.categoriaId(),BootstrapData.RESTAURANT_ID)==0)throw bad("Categoría inválida");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO producto(id,restaurante_id,categoria_id,nombre,descripcion,precio,disponible,activo,version) VALUES (?,?,?,?,?,?,?,true,1)",id,BootstrapData.RESTAURANT_ID,i.categoriaId(),i.nombre().trim(),i.descripcion(),i.precio(),i.disponible());syncEvents.record(id,1,"PRODUCTO_ACTUALIZADO",Map.of("id",id,"categoriaId",i.categoriaId(),"nombre",i.nombre().trim(),"descripcion",i.descripcion()==null?"":i.descripcion(),"precio",i.precio(),"disponible",i.disponible(),"activo",true));return Map.of("id",id,"nombre",i.nombre().trim(),"precio",i.precio());}
    @Transactional @PatchMapping("/products/{id}") public Object updateProduct(@PathVariable UUID id,@Valid @RequestBody ProductInput i,HttpSession s){AuthController.require(s,"ADMINISTRADOR");if(jdbc.queryForObject("SELECT count(*) FROM categoria WHERE id=? AND restaurante_id=? AND activa",Integer.class,i.categoriaId(),BootstrapData.RESTAURANT_ID)==0)throw bad("Categoría inválida");int n=jdbc.update("UPDATE producto SET categoria_id=?,nombre=?,descripcion=?,precio=?,disponible=?,actualizado_en=now(),version=version+1 WHERE id=? AND restaurante_id=?",i.categoriaId(),i.nombre().trim(),i.descripcion(),i.precio(),i.disponible(),id,BootstrapData.RESTAURANT_ID);if(n==0)throw missing("Producto no encontrado");long version=jdbc.queryForObject("SELECT version FROM producto WHERE id=?",Long.class,id);syncEvents.record(id,version,"PRODUCTO_ACTUALIZADO",Map.of("id",id,"categoriaId",i.categoriaId(),"nombre",i.nombre().trim(),"descripcion",i.descripcion()==null?"":i.descripcion(),"precio",i.precio(),"disponible",i.disponible(),"activo",true));return Map.of("actualizado",true);}
    @Transactional @PostMapping("/orders") public Object createOrder(@Valid @RequestBody OrderInput i,@RequestHeader(value="Idempotency-Key",required=false) String idem,HttpSession s){
        AuthController.require(s,"MESERO","ADMINISTRADOR");if(idem==null||idem.isBlank())throw bad("La cabecera Idempotency-Key es obligatoria");if(!Set.of("MESA","DOMICILIO").contains(i.tipo()))throw bad("Tipo de pedido inválido");if(idem.length()>120)throw bad("La clave de idempotencia excede 120 caracteres");UUID employee=AuthController.userId(s);var old=jdbc.queryForList("SELECT id FROM pedido WHERE restaurante_id=? AND idempotency_key=?",BootstrapData.RESTAURANT_ID,idem);if(!old.isEmpty())return order((UUID)old.get(0).get("id"),true);
        if(i.tipo().equals("MESA")){if(i.mesaId()==null)throw bad("Selecciona una mesa");Boolean active=jdbc.query("SELECT activa FROM mesa WHERE id=? AND restaurante_id=? FOR UPDATE",rs->rs.next()?rs.getBoolean(1):null,i.mesaId(),BootstrapData.RESTAURANT_ID);if(!Boolean.TRUE.equals(active))throw bad("La mesa no está disponible");if(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pedido WHERE mesa_id=? AND estado IN ('CONFIRMADO','EN_PREPARACION','LISTO'))",Boolean.class,i.mesaId()))throw conflict("La mesa ya tiene un pedido activo");}else {if(i.mesaId()!=null)throw bad("Un pedido de domicilio no debe incluir mesa");if(i.destino()==null||i.destino().isBlank())throw bad("Indica el destino del domicilio");}
        UUID id=UUID.randomUUID();BigDecimal total=BigDecimal.ZERO;for(var item:i.items()){var products=jdbc.queryForList("SELECT nombre,precio,activo,disponible FROM producto WHERE id=? AND restaurante_id=? FOR UPDATE",item.productoId(),BootstrapData.RESTAURANT_ID);if(products.isEmpty()||!Boolean.TRUE.equals(products.get(0).get("activo"))||!Boolean.TRUE.equals(products.get(0).get("disponible")))throw bad("Un producto no está disponible");var p=products.get(0);BigDecimal price=(BigDecimal)p.get("precio");total=total.add(price.multiply(BigDecimal.valueOf(item.cantidad())));}
        jdbc.update("INSERT INTO pedido(id,restaurante_id,empleado_id,mesa_id,tipo,estado,destino,observaciones,total,idempotency_key,version) VALUES (?,?,?,?,?,'CONFIRMADO',?,?,?,?,1)",id,BootstrapData.RESTAURANT_ID,employee,i.mesaId(),i.tipo(),i.destino(),i.observaciones(),total,idem);
        for(var item:i.items()){var p=jdbc.queryForMap("SELECT nombre,precio FROM producto WHERE id=?",item.productoId());jdbc.update("INSERT INTO detalle_pedido(id,pedido_id,producto_id,nombre_snapshot,precio_snapshot,cantidad,observaciones) VALUES (?,?,?,?,?,?,?)",UUID.randomUUID(),id,item.productoId(),p.get("nombre"),p.get("precio"),item.cantidad(),item.observaciones());}
        jdbc.update("INSERT INTO historial_estado_pedido(id,pedido_id,empleado_id,estado_anterior,estado_nuevo) VALUES (?,?,?,NULL,'CONFIRMADO')",UUID.randomUUID(),id,employee);
        jdbc.update("INSERT INTO trabajo_impresion(id,restaurante_id,pedido_id,estacion,estado,idempotency_key) VALUES (?,?,?,'COCINA','PENDIENTE',?)",UUID.randomUUID(),BootstrapData.RESTAURANT_ID,id,"pedido:"+id);
        var result=order(id,true);recordOrderEvent(id,"PEDIDO_CONFIRMADO");
        publishAfterCommit(result);return result;
    }
    @GetMapping("/orders") public Object orders(@RequestParam(required=false) String estado,HttpSession s){AuthController.require(s,"MESERO","ADMINISTRADOR","COCINA","DOMICILIARIO");String role=AuthController.role(s);String condition=role.equals("DOMICILIARIO")?" AND p.id IN (SELECT pedido_id FROM asignacion_domiciliario WHERE empleado_id=? AND finalizado_en IS NULL)":role.equals("MESERO")?" AND p.empleado_id=?":"";String sql="SELECT p.id,p.tipo,p.mesa_id,m.numero AS mesa_numero,p.estado,CASE WHEN ?='COCINA' THEN NULL ELSE p.destino END AS destino,p.total,p.creado_en FROM pedido p LEFT JOIN mesa m ON m.id=p.mesa_id WHERE p.restaurante_id=?"+condition+(estado==null?"":" AND p.estado=?")+" ORDER BY p.creado_en DESC LIMIT 200";var args=new ArrayList<Object>();args.add(role);args.add(BootstrapData.RESTAURANT_ID);if(!condition.isEmpty())args.add(AuthController.userId(s));if(estado!=null)args.add(estado);var rows=jdbc.queryForList(sql,args.toArray());for(var row:rows)row.put("items",jdbc.queryForList("SELECT nombre_snapshot AS nombre,cantidad,observaciones FROM detalle_pedido WHERE pedido_id=? ORDER BY id",row.get("id")));return rows;}
    @GetMapping("/orders/{id}") public Object getOrder(@PathVariable UUID id,HttpSession s){AuthController.require(s,"MESERO","ADMINISTRADOR","COCINA","DOMICILIARIO");String role=AuthController.role(s);if(role.equals("DOMICILIARIO")&&!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM asignacion_domiciliario WHERE pedido_id=? AND empleado_id=? AND finalizado_en IS NULL)",Boolean.class,id,AuthController.userId(s)))throw forbidden("Este domicilio no está asignado a tu usuario");if(role.equals("MESERO")&&!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pedido WHERE id=? AND empleado_id=? AND restaurante_id=?)",Boolean.class,id,AuthController.userId(s),BootstrapData.RESTAURANT_ID))throw forbidden("Este pedido no está asignado a tu usuario");return order(id,!role.equals("COCINA"));}
    @Transactional @PostMapping("/orders/{id}/assignment") public Object assignDelivery(@PathVariable UUID id,@Valid @RequestBody AssignmentInput i,HttpSession s){String role=AuthController.role(s);AuthController.require(s,"ADMINISTRADOR","MESERO");var type=jdbc.query("SELECT tipo,estado,empleado_id FROM pedido WHERE id=? AND restaurante_id=? FOR UPDATE",rs->rs.next()?rs.getString("tipo")+":"+rs.getString("estado")+":"+rs.getString("empleado_id"):null,id,BootstrapData.RESTAURANT_ID);if(type==null||!type.startsWith("DOMICILIO:")||!Set.of("CONFIRMADO","EN_PREPARACION","LISTO").contains(type.split(":")[1]))throw bad("Pedido de domicilio no asignable");if(role.equals("MESERO")&&!type.endsWith(AuthController.userId(s).toString()))throw forbidden("Solo puedes asignar tus propios domicilios");if(jdbc.queryForObject("SELECT count(*) FROM empleado WHERE id=? AND restaurante_id=? AND rol='DOMICILIARIO' AND activo",Integer.class,i.empleadoId(),BootstrapData.RESTAURANT_ID)==0)throw bad("Domiciliario inválido");jdbc.update("UPDATE asignacion_domiciliario SET finalizado_en=now() WHERE pedido_id=? AND finalizado_en IS NULL",id);UUID assignment=UUID.randomUUID();jdbc.update("INSERT INTO asignacion_domiciliario(id,pedido_id,empleado_id,asignado_por) VALUES (?,?,?,?)",assignment,id,i.empleadoId(),AuthController.userId(s));jdbc.update("UPDATE pedido SET version=version+1 WHERE id=?",id);recordOrderEvent(id,"DOMICILIO_ASIGNADO");return Map.of("id",assignment,"pedidoId",id,"empleadoId",i.empleadoId());}
    @Transactional @PostMapping("/orders/{id}/state") public Object changeState(@PathVariable UUID id,@Valid @RequestBody StateInput i,HttpSession s){String role=AuthController.role(s);String current=jdbc.query("SELECT estado FROM pedido WHERE id=? AND restaurante_id=? FOR UPDATE",rs->rs.next()?rs.getString(1):null,id,BootstrapData.RESTAURANT_ID);if(current==null)throw missing("Pedido no encontrado");if(role.equals("MESERO")&&!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pedido WHERE id=? AND empleado_id=? AND restaurante_id=?)",Boolean.class,id,AuthController.userId(s),BootstrapData.RESTAURANT_ID))throw forbidden("Solo puedes cambiar el estado de tus propios pedidos");if(!OrderStatePolicy.transitionAllowed(current,i.estado()))throw conflict("Transición de estado no permitida");if(!OrderStatePolicy.roleAllowed(role,i.estado()))throw forbidden("Tu rol no puede realizar esta transición");if(role.equals("DOMICILIARIO")&&!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM asignacion_domiciliario WHERE pedido_id=? AND empleado_id=? AND finalizado_en IS NULL)",Boolean.class,id,AuthController.userId(s)))throw forbidden("Este domicilio no está asignado a tu usuario");jdbc.update("UPDATE pedido SET estado=?,version=version+1,actualizado_en=now() WHERE id=?",i.estado(),id);jdbc.update("INSERT INTO historial_estado_pedido(id,pedido_id,empleado_id,estado_anterior,estado_nuevo,motivo) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),id,AuthController.userId(s),current,i.estado(),i.motivo());if(i.estado().equals("ENTREGADO"))jdbc.update("UPDATE asignacion_domiciliario SET finalizado_en=now() WHERE pedido_id=? AND empleado_id=? AND finalizado_en IS NULL",id,AuthController.userId(s));recordOrderEvent(id,"PEDIDO_ESTADO_CAMBIADO");var o=order(id,!role.equals("COCINA"));publishAfterCommit(o);return o;}
    private Object order(UUID id,boolean includePrivate){var orders=jdbc.queryForList("SELECT p.id,p.tipo,p.mesa_id,m.numero AS mesa_numero,p.estado,CASE WHEN ? THEN p.destino ELSE NULL END AS destino,p.observaciones,p.total,p.version,p.creado_en FROM pedido p LEFT JOIN mesa m ON m.id=p.mesa_id WHERE p.id=? AND p.restaurante_id=?",includePrivate,id,BootstrapData.RESTAURANT_ID);if(orders.isEmpty())throw missing("Pedido no encontrado");var out=new HashMap<String,Object>(orders.get(0));out.put("items",jdbc.queryForList("SELECT producto_id,nombre_snapshot AS nombre,precio_snapshot AS precio,cantidad,observaciones FROM detalle_pedido WHERE pedido_id=?",id));return out;}
    private void recordOrderEvent(UUID orderId,String type){long version=jdbc.queryForObject("SELECT version FROM pedido WHERE id=? AND restaurante_id=?",Long.class,orderId,BootstrapData.RESTAURANT_ID);syncEvents.record(orderId,version,type,order(orderId,true));}
    private void publishAfterCommit(Object value){if(!TransactionSynchronizationManager.isSynchronizationActive()){ws.convertAndSend("/topic/kitchen",value);return;}TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){ws.convertAndSend("/topic/kitchen",value);}});}
    @GetMapping("/sync/status") public Object syncStatus(HttpSession s){AuthController.require(s,"ADMINISTRADOR","MESERO");var last=jdbc.queryForList("SELECT ultimo_error FROM evento_outbox WHERE restaurante_id=? AND ultimo_error IS NOT NULL ORDER BY creado_en DESC LIMIT 1",BootstrapData.RESTAURANT_ID);return Map.of("pendientes",jdbc.queryForObject("SELECT count(*) FROM evento_outbox WHERE restaurante_id=? AND estado='PENDIENTE'",Long.class,BootstrapData.RESTAURANT_ID),"conflictos",jdbc.queryForObject("SELECT count(*) FROM evento_outbox WHERE restaurante_id=? AND estado='CONFLICTO'",Long.class,BootstrapData.RESTAURANT_ID),"ultimoError",last.isEmpty()?"":String.valueOf(last.get(0).get("ultimo_error")));}
    public record TableInput(@Min(1) int numero){} public record TableUpdate(boolean activa){} public record CategoryInput(@NotBlank @Size(max=100)String nombre){} public record AssignmentInput(@NotNull UUID empleadoId){}
    public record ProductInput(@NotNull UUID categoriaId,@NotBlank @Size(max=160)String nombre,@Size(max=500)String descripcion,@NotNull @DecimalMin("0.00") @Digits(integer=10,fraction=2)BigDecimal precio,boolean disponible){}
    public record OrderLine(@NotNull UUID productoId,@Min(1) @Max(100)int cantidad,@Size(max=500)String observaciones){}
    public record OrderInput(@NotBlank String tipo,UUID mesaId,@Size(max=500)String destino,@Size(max=1000)String observaciones,@NotEmpty List<@Valid OrderLine> items){}
    public record StateInput(@NotBlank String estado,@Size(max=500)String motivo){}
}
